package dev.seedgenglobe.dh;

/** Added to Distant Horizons' provider of generated LOD data by {@code GeneratedFullDataSourceProviderMixin}. */
public interface DhProviderHook {

	/** Whether the sections this provider is missing are generated by SeedGenGlobe. */
	boolean seedgenglobe$generatedBySeedGenGlobe();

	/** Whether anything can generate this provider's missing sections right now (Distant Generation is on). */
	boolean seedgenglobe$canGenerateNow();
}
